// core/session/meta.hpp — the sidebar's data: main.js collectMeta, ported. One meta object per tile and the
// whole-deck snapshot every view draws from (the `meta` of the init / meta frames and of deskInit's answer).
// PURE: plain structs in, JSON out. Field names, and which fields are null rather than absent, are the
// JS's; core/test/fixtures/session/meta.json is generated by running the real collectMeta (lifted out of
// main.js into a sandbox) over the same inputs.
//
// collectMeta is not a pure read in the JS either: each pass stamps the tile (lastStatus, busySince,
// lastStoppedAt, waitingFor, knownTitle, bridge, lastStoppedInit) and that is what turns "busy last time,
// idle now" into the sidebar's ordering key. tileMeta() does the same stamping on the TileState it is given.
//
// Cloud tiles (kind 'cloud'): their STATUS is decided here from what lib/cloud.js last read (TileTick::cloud);
// main.js cloudMeta's overlay of the other fields is applied by the deck (core/deck/deck.cpp), which has the ids.
// Not ported here: the startup-dialog reader (lib/startupprompts.js) — its one answer collectMeta uses comes in as an input.
#pragma once
#include "livestate.hpp"
#include "replay.hpp"
#include "transcript.hpp"
#include "../third_party/nlohmann/json.hpp"
#include <optional>
#include <string>
#include <utility>
#include <vector>

namespace deck { namespace session {

using json = nlohmann::json;

// main.js cleanOsc: a window title that is only the executable's path, or Claude Code's idle title, is not a title.
std::optional<std::string> cleanOsc(const std::optional<std::string>& oscTitle);

// What main.js keeps on a tile record, as far as collectMeta reads or writes it. Times are ms epoch; 0 means
// "never" wherever the JS field would be undefined / null / 0.
struct TileState {
  std::string id;
  std::string kind = "shell";                       // 'claude' | 'shell'
  std::optional<std::string> account, sessionId;
  bool pinned = false;
  std::optional<std::string> group, userTitle, knownTitle, oscTitle;
  bool running = false;                             // t.pty
  int ptyCols = 0, ptyRows = 0;                     // t.pty.cols / rows
  bool asleep = false, waking = false;
  double sleptAt = 0;
  double startedAt = 0;
  std::optional<std::string> lastStatus;
  bool lastStoppedInit = false;
  double lastStoppedAt = 0;
  double busySince = 0;
  json waitingFor;                                  // null, or what the session waits on
  std::optional<bool> browser;                      // Claude in Chrome: true / false / the account's default
  std::optional<std::string> desk;
  double attentionAt = 0;
  std::optional<std::string> lastInputFrom;         // 'desktop' | 'phone' | 'deck'
  double lastInputAt = 0;
  double lastKeyAt = 0;
  bool hadInput = false;
  bool exited = false;
  std::optional<int> exitCode;
  std::string cwd;
  Modes modes;
  std::optional<std::pair<int, int>> phoneSize;     // cols, rows a remote last showed it at
  json bridge;                                      // the Claude apps' id for the conversation, once seen
  // a cloud tile (kind 'cloud', lib/cloud.js): its session's id once made (`session_…`), and the task its
  // `claude --cloud "<task>"` run was started from
  std::optional<std::string> cloudId, cloudTask;
};

// What one pass needs from outside the tile.
struct TileTick {
  const LiveRecord* live = nullptr;                 // live.get(t.sessionId)
  const TranscriptTail* tail = nullptr;             // t.tail, already polled; null when there is no transcript yet
  std::vector<std::string> shownBy;                 // shownBy(t): "win:0", "remote"
  std::optional<int> inWindow;                      // the window whose layout holds it
  json held = json::array();                        // held.forTile(t.id)
  double contextWindow = 200000;                    // the account's (1,000,000 with the [1m] model suffix)
  bool resumable = false;                           // isResumable(t): a transcript exists for --resume
  bool remoteWatching = false;                      // phone.running && phone.watching(t.id)
  // t.startup (lib/startupprompts.js), reduced to what collectMeta asks of it
  bool startupOpen = false;                         // a watch exists and is not done
  double startupSince = 0;
  std::optional<std::string> startupWaitTitle;      // startup.waitingOn(now).title, when it is sitting on a dialog
  // a cloud tile's session as lib/cloud.js last read it (cloud.session(t.cloudId)); null until the first read
  const json* cloud = nullptr;
};

// What the pass asks the caller to do (the JS does these inline).
struct TickEffects {
  bool finishStartup = false;                       // t.startup.finish()
  bool notify = false;                              // maybeNotify(t, notifyStatus, turnMs)
  std::string notifyStatus;
  double turnMs = 0;
};

// lib/hibernate.js config(): the settings' hibernate block, clamped and defaulted.
struct HibernateConfig { bool enabled = true; int idleMinutes = 30; bool keepPinned = true; int maxPerTick = 3; };
HibernateConfig hibernateConfig(const json& settingsHibernate);

// One tile's meta. `settings` is the deck's whole settings object (driver, hibernate are read).
json tileMeta(TileState& t, const TileTick& in, double now, const json& settings, TickEffects* effects = nullptr);

// meta.settings: the subset of the settings every view is given. `pagesShown` is settings.pages after the
// page viewer has given each an id ([{ label, id, … }]); the phone never sees a path.
json settingsMeta(const json& settings, const json& pagesShown = json::array());

// meta.restart with nothing armed (lib/quietrestart.js): what is in the way of a restart, and how many
// terminal tiles one would bring back empty.
struct QuietView {
  std::string id;
  std::optional<std::string> title;
  std::string kind, status;
  bool running = false, asleep = false;
  double busySince = 0;
  json waitingFor;
  std::vector<BackgroundWork> background;
  double lastKeyAt = 0;
};
json restartBlockers(const std::vector<QuietView>& views, double now);
int shellsLost(const std::vector<QuietView>& views);
json restartViewUnarmed(const json& blockers, int shells);
// quietViews(): the view of one tile, from its state after tileMeta() ran (title = the meta's title)
QuietView quietView(const TileState& t, const json& meta, const TranscriptTail* tail, double now);

struct DeckInputs {
  double now = 0;
  bool restoring = false;
  json accounts = json::array();                    // publicAccounts(): [{ id, label, abbr, email, key, isDefault }]
  json settings = json::object();                   // the whole settings object
  json pagesShown = json::array();
  std::vector<std::string> groups;
  json usage = json::object();
  json triggers = json::array();
  json restart;                                     // restartViewUnarmed(…) or the armed view
  json asks = json::array();
  json askLog = json::array();
};
// The snapshot: pinned tiles first in the order given (array order IS the pinned order), then the rest by
// lastStoppedAt, newest first (a stable sort: equal stamps keep the order given).
json deckMeta(const DeckInputs& in, const std::vector<std::pair<bool, json>>& tilesPinnedAndMeta);

}}  // namespace deck::session
